\use strict";
var items = [[196481,[196481,196480,196482]],[196542,[196542,196541,196543]],[196603,[196603,196602,196604]],[196607,[196607,196606,196608]]];
var out = [];
for (var i = 0; i < items.length; i++) {
  for (var f = 0; f < 2; f++) {
    var re = new RegExp("\\u{" + items[i][0].toString(16) + "}", f ? "iv" : "iu");
    var row = "";
    for (var j = 0; j < items[i][1].length; j++) row += re.test(String.fromCodePoint(items[i][1][j])) ? "1" : "0";
    out.push(row);
  }
}
globalThis.R = out.join("|")"

